        if method == ""say"":
            self.say(user.name + "", "" + lowercase_first_letter(message))
        elif method == ""whisper"":
            self.whisper(user, message)
        elif method == ""me"":
            self.me(message)
        elif method == ""reply"":
            if event.type in [""action"", ""pubmsg""]:
                self.say(message)
            elif event.type == ""whisper"":
                self.whisper(user, message)
        else:
            log.warning(""Unknown send_message method: %s"", method)"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",[],[],True,skipped_fixer_only,"def get_user_tokens(self, bot, event, source, **rest):

